import {DEFAULT_QUESTIONS,DEFAULT_PROFILE,buildQueue,analyzeAnswer,compareAnswers,summarizeSession,ensureDraft} from './domain.js';

import {createFeatures} from './features.js';
import {validateQuestion} from './portability.js';
const KEY='preplab.v1';
const $=(s)=>document.querySelector(s);
const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',mic:'M9 5a3 3 0 0 1 6 0v7a3 3 0 0 1-6 0z M5 10v2a7 7 0 0 0 14 0v-2 M12 19v3 M8 22h8',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',layers:'m12 3 10 5-10 5L2 8z M2 12l10 5 10-5 M2 16l10 5 10-5',settings:'M9 3h6l1 4 4 2v6l-4 2-1 4H9l-1-4-4-2V9l4-2z M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6',arrow:'M4 12h16 M14 6l6 6-6 6',play:'m8 4 13 8-13 8z',code:'m8 7-5 5 5 5 m8-10 5 5-5 5 M14 4l-4 16',check:'m5 12 4 4L19 6',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',edit:'m4 15 12-12 5 5L9 20l-6 1z M13 6l5 5',close:'m6 6 12 12 M18 6 6 18',calendar:'M4 5h16v16H4z M8 3v4 M16 3v4 M4 10h16',file:'M5 3h9l5 5v13H5z M14 3v6h5 M8 13h8 M8 17h6',repeat:'M4 7h13l3 3 M20 3v7h-7 M20 17H7l-3-3 M4 21v-7h7',pause:'M8 5v14 M16 5v14',trash:'M4 6h16 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 11v6 M12 7v.5',plus:'M12 5v14 M5 12h14',upload:'M12 17V3 M7 8l5-5 5 5 M4 16v5h16v-5'};
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));

let storageNotice=false;
function readStore(){try{const d=JSON.parse(localStorage.getItem(KEY)||'null');if(d&&Array.isArray(d.questions)&&d.questions.length&&Array.isArray(d.history)){return {...d,profile:{...DEFAULT_PROFILE,...d.profile}};}}catch{}return {profile:{...DEFAULT_PROFILE},questions:structuredClone(DEFAULT_QUESTIONS),history:[],active:null};}
let state=readStore();
let reportId=null;
let hintOpen=false;
let toastTimer;
let recorder=null,mediaStream=null,recordStarted=0,micPending=false,recordingDone=Promise.resolve();
let audioURLs=new Map();
const features=createFeatures({getState:()=>state,setState:v=>{state=v;reportId=null;},current,question,draft,selectedReport,esc,icon,toast,save,render,modal,closeDialog,go,download,stopMic,audioURLs});
const dialog=$('#dialog');
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3800);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{if(!storageNotice){toast('瀏覽器無法保存紀錄；目前內容仍可使用，請匯出後再離開。');storageNotice=true;}}}
function uid(){return crypto.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`;}
function formatDate(iso){return new Intl.DateTimeFormat('zh-TW',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(iso));}
const duration=(secs)=>`${String(Math.floor(secs/60)).padStart(2,'0')}:${String(secs%60).padStart(2,'0')}`;
function go(view){if(location.hash===`#${view}`)render();else location.hash=view;}
function closeDialog(){dialog.close();dialog.innerHTML='';}
function modal(title,body,actions=''){dialog.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${esc(title)}</h2><button class="icon-button" data-action="close-dialog" aria-label="關閉">${icon('close')}</button></div>${body}${actions}`;dialog.showModal();}
function confirmAction(title,text,action){modal(title,`<div class="dialog-body"><p class="muted">${esc(text)}</p></div>`,`<div class="dialog-actions"><button class="btn" data-action="close-dialog">取消</button><button class="btn danger" data-action="${action}">確認</button></div>`);}
function heading(kicker,title,desc,action=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p class="subtitle">${desc}</p></div>${action}</div>`;}
function stat(label,value,unit,ico,aside=''){return `<div class="metric"><div class="metric-icon">${icon(ico)}</div><div><div class="metric-label">${label}</div><strong>${value}<span class="unit">${unit}</span></strong></div>${aside?`<span class="aside">${aside}</span>`:''}</div>`;}
function current(){return state.active;}
function question(){return current()?.questions[current().index];}
function draft(){const s=current(),q=question();if(!s||!q)return null;s.drafts??={};return ensureDraft(s.drafts,q.id,q.code||'');}
function audioKey(){return current()?`${current().id}:${question()?.id}`:'';}
async function stopMic(){if(recorder?.state==='recording')recorder.stop();mediaStream?.getTracks().forEach(t=>t.stop());mediaStream=null;await recordingDone;await features.waitAudio();}

function dashboard(){
 const summaries=state.history.map(summarizeSession),answers=summaries.reduce((n,s)=>n+s.answered,0),retakes=summaries.reduce((n,s)=>n+s.retakes,0);
 return `${heading('YOUR NEXT CHAPTER','把實力，說得更清楚。','從一次工程面試練習開始，找到下一步可以改善的地方。',`<div class="date-chip">${icon('calendar')} ${new Intl.DateTimeFormat('zh-TW',{month:'long',day:'numeric',weekday:'short'}).format(new Date())}</div>`)}
 ${state.active?`<div class="resume-banner"><span>你有一場尚未完成的練習，進度已保留。</span><button class="btn small soft" data-action="resume">繼續練習 ${icon('arrow')}</button></div>`:''}
 <section class="hero"><div class="hero-text"><span class="pill"><span class="tiny-dot"></span> YOUR PERSONAL INTERVIEW SPACE</span><h2>下一次面試，<br>從這次練習開始。</h2><p>練習技術思考，也練習把思路說清楚。<br>在熟悉的工程情境裡，準備更好的自己。</p><div class="hero-actions"><a class="btn primary" href="#setup">開始一場練習 ${icon('arrow')}</a><button class="text-button" data-action="tour">先看看練習流程 ${icon('play')}</button></div></div><div class="hero-visual" aria-label="程式答辯練習示意"><div class="code-preview"><div class="windowbar"><i></i><i></i><i></i><span>interview.cpp</span></div><pre><span style="color:#6d8f78">// 說出你的思考過程</span>\n<b>int</b> findMax(<b>const</b> vector&lt;<b>int</b>&gt;&amp; a) {\n  <b>int</b> result = a[0];\n  <b>for</b> (<b>int</b> value : a)\n    result = max(result, value);\n  <b>return</b> result;\n}\n<span style="color:#6d8f78">// 如果輸入是空的呢？</span></pre><div class="visual-voice">${icon('mic')} 解釋你的解法<span class="wave" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></span></div></div></div></section>
 <div class="metrics">${stat('已完成練習',state.history.length,'場','check','慢慢累積，持續進步')}${stat('已作答題目',answers,'題','code')}${stat('完成重答',retakes,'次','repeat')}</div>
 <div class="dashboard-grid"><section><div class="section-title"><h2>這次的目標 <small>FOCUS ON YOUR NEXT ROLE</small></h2></div><div class="panel"><div class="role-head"><span class="company-mark">M</span><div><h3>MediaTek 聯發科技</h3><small>公開職缺情境 · 軟體與韌體方向</small></div><span class="tag">目標公司</span></div><p class="role-desc">${esc(state.profile.role)}<br>從 C／C++、問題分析到專案經驗，練習有依據地說明你的選擇。</p><div class="tag-row"><span class="tag">C / C++</span><span class="tag">系統觀念</span><span class="tag">程式答辯</span><span class="tag">專案表達</span></div><div class="role-bottom"><span>題目與難度都能在題目管理調整</span><a href="#setup" class="text-button">設定練習 ${icon('arrow')}</a></div></div></section><section><div class="section-title"><h2>每一場，都有下一步</h2></div><div class="panel"><div class="step-row"><span class="step-number">01</span><div><h3>設定你的面試背景</h3><p>填入履歷重點與職缺，確認練習方向。</p></div></div><div class="step-row"><span class="step-number">02</span><div><h3>解題，也說明你的思路</h3><p>在同一個空間閱讀程式、作答與追問。</p></div></div><div class="step-row"><span class="step-number">03</span><div><h3>回顧之後，再回答一次</h3><p>對照前後回答，看看你補充了什麼。</p></div></div></div></section></div>
 <section class="section-space"><div class="section-title"><h2>最近的練習</h2><a class="text-button" href="#history">查看全部 ${icon('arrow')}</a></div>${state.history.length?historyTable(state.history.slice(0,3)):`<div class="empty-row"><div class="empty-message">${icon('clock')}<span>還沒有練習紀錄。第一場，不需要完美。</span></div><a href="#setup" class="text-button">開始累積你的進步 ${icon('arrow')}</a></div>`}</section>`;
}

function setup(){const p=state.profile;return `${heading('MAKE IT YOURS','準備你的練習','先設定背景，再進入面試室。內容可以隨時調整。')}
 <form id="setup-form"><div class="form-grid"><div><section class="panel form-panel"><h2>01 <span class="muted">／</span> 面試目標</h2><div class="role-head" style="margin-bottom:23px"><span class="company-mark">M</span><div><h3>MediaTek 聯發科技</h3><small>以公開職缺為情境，非官方面試或題庫</small></div></div><label class="field"><span>目標職務</span><input name="role" value="${esc(p.role)}" maxlength="100" required placeholder="例如：系統軟體／韌體工程師"></label><div class="form-pair"><label class="field"><span>難度偏好</span><select name="difficulty"><option ${p.difficulty==='基礎'?'selected':''}>基礎</option><option ${p.difficulty==='進階'?'selected':''}>進階</option></select><small>優先安排偏好難度，不足時搭配其他題目。</small></label><label class="field"><span>練習題數</span><select name="count"><option value="3" ${p.count===3?'selected':''}>3 題 · 快速練習</option><option value="5" ${p.count===5?'selected':''}>5 題 · 完整練習</option></select><small>實際題數以目前題庫數量為上限。</small></label></div><label class="field"><span>職缺重點 <span class="optional">可修改</span></span><textarea name="jd" maxlength="12000" placeholder="貼上想練習的職缺能力要求">${esc(p.jd)}</textarea></label></section>
 <section class="panel form-panel"><h2>02 <span class="muted">／</span> 關於你</h2><label class="field"><span>怎麼稱呼你 <span class="optional">選填</span></span><input name="name" maxlength="50" value="${esc(p.name)}" placeholder="輸入暱稱即可"></label><div class="field-toolbar"><label for="resume">履歷與專案重點 <span class="muted">（選填）</span></label><button type="button" class="text-button" data-action="sample-resume">帶入範例</button></div><textarea id="resume" name="resume" class="textarea-block" rows="7" maxlength="20000" placeholder="可以寫下你做過的專案、使用的技術，以及想練習說明的經驗。">${esc(p.resume)}</textarea><div class="field" style="margin-top:12px"><input type="file" id="resume-file" accept=".txt,.md,text/plain" aria-label="匯入文字履歷"><small>支援 TXT／Markdown。PDF 可先複製文字貼上。示範模式資料保存在本機；GPT 模式會將背景與回答送往 OpenAI。</small></div></section></div>
 <aside class="panel side-summary"><div class="summary-art">${icon('mic')}</div><h2>給自己一個練習的空間</h2><div class="detail-line"><span>面試形式</span><b>程式與文字答辯</b></div><div class="detail-line"><span>語音功能</span><b>本機錄音與回聽</b></div><div class="detail-line"><span>追問安排</span><b>每題最多 1 次</b></div><div class="detail-line"><span>練習結束</span><b>回顧與重答比較</b></div><div class="note">這是可操作的示範模式。題目採預設內容，履歷與職缺目前只保存為背景，尚未用 AI 個人化出題。錄音不會自動辨識，請同時輸入回答重點。</div><button class="btn primary full" type="submit">進入面試室 ${icon('arrow')}</button><p class="subtitle" style="text-align:center;font-size:10px">開始後自動保存文字與程式進度</p></aside></div></form>`;}

function room(){const s=current();if(!s)return `${heading('INTERVIEW ROOM','先設定一場練習','設定面試目標後，就可以開始。')}<a class="btn primary" href="#setup">設定練習 ${icon('arrow')}</a>`;const q=question(),d=draft(),audio=audioURLs.get(audioKey());return `<div class="session-top"><div class="session-title"><h1>面試練習室</h1><span class="tag">${esc(s.profile.role)}</span></div><div class="session-controls"><span class="timer" id="timer">${duration(s.elapsed||0)}</span><button class="btn small" data-action="pause">${icon(s.paused?'play':'pause')} ${s.paused?'繼續':'暫停'}</button><button class="text-button" data-action="finish-early">結束</button></div></div>
 <div class="session-progress" aria-label="目前第 ${s.index+1} 題，共 ${s.questions.length} 題">${s.questions.map((_,i)=>`<span class="${i<s.index?'done':i===s.index?'current':''}"></span>`).join('')}</div>
 ${s.paused?'<div class="paused-banner">練習已暫停，計時與作答已暫停。點「繼續」回到練習。</div>':''}
 <div class="room-grid"><section class="panel question-panel"><div class="question-index">QUESTION ${String(s.index+1).padStart(2,'0')} / ${String(s.questions.length).padStart(2,'0')}</div><div class="tag-row"><span class="tag">${esc(q.category)}</span><span class="tag">${esc(q.level)}</span></div><h2>${esc(q.title)}</h2><p class="question-prompt">${esc(q.prompt)}</p>${q.code?`<div class="code-box"><div class="code-toolbar"><span>solution.cpp · 可直接編輯</span><button class="text-button" style="color:#b3c8ac;font-size:10px" data-action="reset-code" ${s.paused?'disabled':''}>重設程式</button></div><textarea id="code-editor" class="code-editor" aria-label="程式作答區" spellcheck="false" ${s.paused?'disabled':''}>${esc(d.code)}</textarea></div><p class="subtitle" style="font-size:10px">程式會保存至報告；程式只供閱讀分析，不會編譯或執行。</p>`:`<div class="note">可以先想一想：當時的問題是什麼？你做了什麼選擇？你如何確認結果？</div>`}<div class="question-hint"><button class="text-button" data-action="hint">${icon('info')} ${hintOpen?'收起提示':'需要一點提示？'}</button>${hintOpen?`<p>${esc(q.hint)}</p>`:''}</div></section>
 <section class="panel"><div class="interviewer"><span class="bot-avatar">${icon('mic')}</span><div><h3>你的面試練習夥伴</h3><small>示範對話 · 尚未連接 AI</small></div><span class="tiny-dot" style="margin-left:auto"></span></div><div class="message">先說說你會怎麼思考這個問題，再補充你的理由與驗證方式。你可以修改左側程式，也可以先用文字整理思路。</div><div class="answer-label"><label for="answer">你的回答重點</label><span id="char-count">${analyzeAnswer(d.text,q).wordCount} 字元</span></div><textarea id="answer" class="answer-area" maxlength="20000" placeholder="在這裡寫下你的分析、作法與理由……" ${s.paused?'disabled':''}>${esc(d.text)}</textarea><div class="mic-row"><button class="mic-button ${recorder?.state==='recording'?'recording':''}" data-action="mic" ${s.paused?'disabled':''}>${icon('mic')} <span id="mic-label">${recorder?.state==='recording'?'停止錄音':'錄下口頭回答'}</span></button><span class="mic-note">僅供回聽，不會自動轉成文字</span></div>${audio?`<audio controls class="audio-play" src="${audio}" aria-label="回聽本題錄音"></audio><p class="mic-note">錄音會保存在此瀏覽器，可從資料設定完整備份。</p>`:''}
 ${d.followupShown?`<div class="followup"><div class="answer-label">一次追問 <span>示範規則產生</span></div><div class="message">${esc(d.followupPrompt)}</div><label class="answer-label" for="followup-answer">補充你的回答</label><textarea id="followup-answer" class="answer-area" style="min-height:100px" maxlength="10000" placeholder="補充限制、測試方法或實際經驗……" ${s.paused?'disabled':''}>${esc(d.followupText)}</textarea></div>`:''}
 <div class="answer-actions">${!d.followupShown?`<button class="btn" data-action="followup" ${s.paused?'disabled':''}>查看示範追問 ${icon('plus')}</button>`:''}<button class="btn primary" data-action="next" ${s.paused?'disabled':''}>${s.index===s.questions.length-1?'完成並查看回顧':'保存並下一題'} ${icon('arrow')}</button></div><div class="save-state">文字與程式進度已自動保存在此瀏覽器</div></section></div><div class="session-disclaimer">${icon('info')} 示範模式提供固定題目與規則式追問，尚未進行 AI 理解或技術評分。</div>`;}

function historyTable(sessions){return `<div class="table-wrap"><table><thead><tr><th>練習目標</th><th>完成時間</th><th>作答</th><th>重答</th><th style="text-align:right">操作</th></tr></thead><tbody>${sessions.map(s=>{const m=summarizeSession(s);return `<tr><td>${esc(s.profile.role)}<span class="cell-sub">MediaTek 情境 · ${s.mode==='ai'?'GPT 面試':'示範練習'}</span></td><td>${formatDate(s.finishedAt)}</td><td>${m.answered} / ${m.total} 題</td><td>${m.retakes} 次</td><td><div class="row-actions"><button class="text-button" data-action="report" data-id="${esc(s.id)}">查看回顧 ${icon('arrow')}</button><button class="icon-button" data-action="delete-session" data-id="${esc(s.id)}" aria-label="刪除此場練習">${icon('trash')}</button></div></td></tr>`;}).join('')}</tbody></table></div>`;}
function history(){return `${heading('YOUR PRACTICE JOURNEY','每一次練習，都留下軌跡。','回顧作答與重答紀錄。這裡只顯示你實際完成的練習。',`<a href="#setup" class="btn primary">新增練習 ${icon('plus')}</a>`)}${state.history.length?historyTable(state.history):`<div class="empty-large">${icon('clock')}<h2>你的第一場練習，從這裡開始</h2><p>完成練習後，回答、程式與回顧會保存在這裡。</p><a class="btn primary" href="#setup">開始練習 ${icon('arrow')}</a></div>`}`;}
function originalAnswer(a){return [a?.text,a?.followupText?'追問補充：'+a.followupText:''].filter(Boolean).join('\n\n');}
function selectedReport(){return state.history.find(s=>s.id===reportId)||state.history[0];}
function report(){const s=selectedReport();if(!s)return history();const m=summarizeSession(s);return `${heading('REFLECT. REFINE. REPEAT.','看見這次的練習','MediaTek 情境 · '+esc(s.profile.role)+' · '+formatDate(s.finishedAt),`<button class="btn" data-action="export-report">${icon('download')} 匯出回顧</button>`)}<div class="report-banner"><div><h2>你已完成這一場練習。</h2><p>回到當時的回答，補上還沒說清楚的地方。</p></div><div class="total-number">${m.answered}<small> / ${m.total} 題</small></div></div><div class="metrics">${stat('累積作答',m.answered,'題','check')}${stat('回答內容',m.totalChars,'字元','file')}${stat('重答練習',m.retakes,'次','repeat')}</div><div class="note">目前回顧為規則式示範，不是 AI 技術評分。下方標記只檢查是否出現題目相關字詞，不能代表回答正確、能力提升或錄取機率。</div><div class="section-title"><h2>逐題回顧 <small>從具體回答開始改善</small></h2><a href="#setup" class="text-button">再練習一場 ${icon('arrow')}</a></div>${s.questions.map((q,i)=>{const a=s.answers.find(a=>a.questionId===q.id);const result=analyzeAnswer(originalAnswer(a),q);const comparison=a?.retakeText?compareAnswers(originalAnswer(a),a.retakeText,q):null;return `<section class="panel report-card"><div class="report-card-head"><h3><span class="muted">${String(i+1).padStart(2,'0')} ／</span> ${esc(q.title)}</h3>${a?`<button class="btn small soft" data-action="retake" data-id="${esc(q.id)}">${icon('repeat')} ${a.retakeText?'更新重答':'再回答一次'}</button>`:'<span class="tag">本次未作答</span>'}</div><p class="feedback-note">${esc(q.prompt)}</p><div class="quote">${esc(a?.text||'尚無文字回答紀錄。')}</div>${a?.followupText?`<p class="compare-label" style="margin-top:12px">追問回答</p><div class="quote">${esc(a.followupText)}</div>`:''}${a?.code?`<details><summary>查看保存的程式</summary><pre class="code-snapshot">${esc(a.code)}</pre></details>`:''}${a?`<div class="feedback-list">${result.checks.map(c=>`<span class="feedback-item ${c.matched?'matched':''}">${c.matched?'✓ 已提及':'○ 可補充'} ${esc(c.label)}</span>`).join('')}</div><p class="feedback-note">${esc(q.hint)}</p>`:''}${comparison?`<div class="divider"></div><div class="section-title"><h3>重答前後比較</h3><span class="tag">相同題目</span></div><div class="compare-grid"><div><p class="compare-label">第一次（含追問）· ${comparison.before.wordCount} 字元</p><div class="quote">${esc(originalAnswer(a))}</div></div><div><p class="compare-label">重答後 · ${comparison.after.wordCount} 字元</p><div class="quote">${esc(a.retakeText)}</div></div></div><p class="feedback-note">${comparison.newlyMentioned.length?'重答新增提及：'+comparison.newlyMentioned.map(esc).join('、')+'。':'尚未偵測到新增的預設關鍵詞，可直接對照兩次回答。'} 此比較不判定技術正確性。</p>${a.retakeCode&&a.retakeCode!==a.code?`<details><summary>查看重答後的程式</summary><pre class="code-snapshot">${esc(a.retakeCode)}</pre></details>`:''}`:''}</section>`;}).join('')}`;}

function questions(){return `${heading('SHAPE YOUR PRACTICE','把題目，調成適合你的樣子。','題目內容、難度與追問皆可編輯。修改只影響之後的新練習。',`<div class="header-actions"><button class="btn" data-action="export-questions">${icon('download')} 匯出</button><button class="btn primary" data-action="new-question">${icon('plus')} 新增題目</button></div>`)}<div class="section-title"><h2>練習題庫 <small>${state.questions.length} 題 · 本機保存</small></h2><div class="toolbar"><button class="text-button" data-action="import-questions">${icon('upload')} 匯入 JSON</button><button class="text-button" data-action="restore-questions">恢復範例</button></div></div><div class="question-list">${state.questions.map((q,i)=>`<article class="question-row"><span class="num">${String(i+1).padStart(2,'0')}</span><div class="question-row-content"><h3>${esc(q.title)}</h3><p>${esc(q.prompt)}</p><div class="question-meta"><span class="tag">${esc(q.category)}</span><span class="tag">${esc(q.level)}</span>${q.code?'<span class="tag">含程式情境</span>':''}</div></div><button class="btn small" data-action="edit-question" data-id="${esc(q.id)}">${icon('edit')} 編輯</button><button class="icon-button" data-action="delete-question" data-id="${esc(q.id)}" aria-label="刪除題目 ${esc(q.title)}">${icon('trash')}</button></article>`).join('')}</div><div class="note">這些是課程展示用情境，並非聯發科真實面試題。新增或修改的題目可以立即用於示範流程；內容正確性仍需由團隊確認。</div><input type="file" id="question-file" accept=".json,application/json" hidden>`;}

function editQuestion(id){const q=state.questions.find(q=>q.id===id)||{id:'',title:'',category:'自訂情境',level:'基礎',prompt:'',code:'',followup:'你會如何驗證這個做法？',hint:'試著補充具體作法、選擇理由與驗證方式。',checks:[]};modal(q.id?'編輯練習題目':'新增練習題目',`<form id="question-form" data-id="${esc(q.id)}"><div class="dialog-body"><label class="field"><span>題目名稱</span><input name="title" required maxlength="100" value="${esc(q.title)}"></label><div class="form-pair"><label class="field"><span>分類</span><input name="category" required maxlength="50" value="${esc(q.category)}"></label><label class="field"><span>難度</span><select name="level"><option ${q.level==='基礎'?'selected':''}>基礎</option><option ${q.level==='進階'?'selected':''}>進階</option></select></label></div><label class="field"><span>面試題目</span><textarea name="prompt" maxlength="10000" required>${esc(q.prompt)}</textarea></label><label class="field"><span>程式片段 <span class="optional">選填，留空為一般問答</span></span><textarea name="code" maxlength="30000" spellcheck="false" style="font-family:var(--mono)">${esc(q.code)}</textarea></label><label class="field"><span>示範追問</span><input name="followup" required maxlength="1000" value="${esc(q.followup)}"></label><label class="field"><span>提示與回顧重點</span><textarea name="hint" required maxlength="3000">${esc(q.hint)}</textarea></label><label class="field"><span>字詞提示規則 <span class="optional">選填，不代表技術評分</span></span><textarea name="checks" rows="3" placeholder="驗證方法 | 測試,驗證\n邊界情況 | 空陣列,邊界">${esc(q.checks.map(c=>`${c.label} | ${c.keywords.join(',')}`).join('\n'))}</textarea><small>每行：顯示名稱 | 關鍵詞,關鍵詞。只用於示範回顧的字面提及標記。</small></label></div><div class="dialog-actions"><button type="button" class="btn" data-action="close-dialog">取消</button><button class="btn primary" type="submit">保存題目 ${icon('check')}</button></div></form>`);}
function editRetake(qid){const s=selectedReport(),q=s.questions.find(q=>q.id===qid),a=s.answers.find(a=>a.questionId===qid);if(!a)return;modal('再回答一次',`<form id="retake-form" data-id="${esc(qid)}"><div class="dialog-body"><h3>${esc(q.title)}</h3><div class="note">${esc(q.hint)}</div><p class="compare-label">第一次的回答（含追問）</p><div class="quote">${esc(originalAnswer(a)||'未輸入文字回答')}</div><label class="field" style="margin-top:20px"><span>這一次，你會怎麼說？</span><textarea name="retakeText" required maxlength="20000" style="min-height:160px" placeholder="補充你的理由、方法或驗證方式……">${esc(a.retakeText||'')}</textarea></label>${q.code?`<label class="field"><span>程式修改 <span class="optional">不執行</span></span><textarea name="retakeCode" maxlength="30000" spellcheck="false" style="font-family:var(--mono)">${esc(a.retakeCode||a.code||q.code)}</textarea></label>`:''}</div><div class="dialog-actions"><button type="button" class="btn" data-action="close-dialog">取消</button><button type="submit" class="btn primary">保存並比較 ${icon('arrow')}</button></div></form>`);}
function download(text,name,type='text/plain;charset=utf-8'){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),3000);toast('已準備下載檔案');}
function exportReport(){const s=selectedReport();if(!s)return;let out=`# PrepLab 練習回顧\n\n目標：${s.profile.role}\n時間：${formatDate(s.finishedAt)}\n\n此回顧包含已保存的作答；GPT 內容如有生成會另外列出。程式未執行，不代表錄取判斷。\n`;for(const q of s.questions){const a=s.answers.find(a=>a.questionId===q.id);out+=`\n## ${q.title}\n\n${q.prompt}\n\n回答：\n${a?.text||'未作答'}\n`;if(a?.code)out+=`\n程式：\n\n\`\`\`cpp\n${a.code}\n\`\`\`\n`;if(a?.followupText)out+=`\n追問：${a.followupPrompt||q.followup}\n\n補充：${a.followupText}\n`;if(a?.retakeText)out+=`\n重答：\n${a.retakeText}\n`;if(a?.retakeCode)out+=`\n重答程式：\n\n\`\`\`cpp\n${a.retakeCode}\n\`\`\`\n`;if(a?.aiFeedback)out+=`\n### GPT 回饋\n\n${a.aiFeedback.data.summary}\n`+a.aiFeedback.data.strengths.map(x=>`- ${x.point}；依據：${x.evidence}\n`).join('')+a.aiFeedback.data.improvements.map(x=>`- ${x.point}；依據：${x.evidence}；建議：${x.suggestion}\n`).join('')+`\n未評估：${a.aiFeedback.data.unassessed.join('、')}\n模型：${a.aiFeedback.meta.model}\n`;if(a?.aiComparison)out+=`\n### GPT 重答比較\n${a.aiComparison.data.summary}\n`+a.aiComparison.data.changes.map(x=>`- ${x.point}：${x.before} → ${x.after}\n`).join('')+`\n仍可補充：${a.aiComparison.data.remaining.join('、')}\n`;out+=`\n回顧提示：${q.hint}\n`;}download(out,`PrepLab-${s.finishedAt.slice(0,10)}.md`,'text/markdown;charset=utf-8');}
function recordAnswer(){const s=current(),q=question(),d=draft();if(!s||!q)return;const existing=s.answers.find(a=>a.questionId===q.id);const hasContent=d.text.trim()||d.followupText.trim()||d.code.trim()!==(q.code||'').trim();if(!hasContent)return;const a={questionId:q.id,...d};if(existing)Object.assign(existing,a);else s.answers.push(a);}
async function finishSession(){await features.disconnect();await stopMic();const s=current();if(!s)return;recordAnswer();s.finishedAt=new Date().toISOString();s.paused=false;state.history.unshift(structuredClone(s));reportId=s.id;state.active=null;save();closeDialog();go('report');}
async function toggleMic(){if(recorder?.state==='recording'){await stopMic();return;}if(micPending)return;if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('此瀏覽器不支援錄音，請使用文字回答。');return;}micPending=true;const key=audioKey(),sessionId=current().id,questionId=question().id;try{mediaStream=await navigator.mediaDevices.getUserMedia({audio:true});if(location.hash!=='#room'||audioKey()!==key||current()?.paused){mediaStream.getTracks().forEach(t=>t.stop());mediaStream=null;return;}const chunks=[];const r=new MediaRecorder(mediaStream);let settleRecording;recordingDone=new Promise(resolve=>{settleRecording=resolve;});recorder=r;recordStarted=Date.now();r.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};r.onstop=async()=>{try{const old=audioURLs.get(key);if(old)URL.revokeObjectURL(old);if(chunks.length){const blob=new Blob(chunks,{type:r.mimeType});audioURLs.set(key,URL.createObjectURL(blob));await features.saveAudio(blob,{sessionId,questionId,slot:'main'});}if(recorder===r)recorder=null;if(location.hash==='#room'&&audioKey()===key)render();}finally{settleRecording();}};r.start();render();}catch{toast('未取得麥克風權限。你仍可使用文字完成練習。');mediaStream?.getTracks().forEach(t=>t.stop());mediaStream=null;}finally{micPending=false;}}

function render(){let view=location.hash.slice(1)||'dashboard';if(!['dashboard','setup','room','history','report','questions'].includes(view))view='dashboard';const labels={dashboard:'練習總覽',setup:'開始面試',room:'面試練習室',history:'練習紀錄',report:'練習回顧',questions:'題目管理'};$('#page-name').textContent=labels[view];document.title=`${labels[view]} · PrepLab`;document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===view||(view==='room'&&a.dataset.nav==='setup')||(view==='report'&&a.dataset.nav==='history');a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});const renderers={dashboard,setup,room,history,report,questions};$('#main').innerHTML=renderers[view]();features.afterRender();}
window.addEventListener('hashchange',()=>{if(location.hash!=='#room')stopMic();hintOpen=false;render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});});
document.addEventListener('input',e=>{if(current()&&['answer','code-editor','followup-answer'].includes(e.target.id)){const d=draft();const field={answer:'text','code-editor':'code','followup-answer':'followupText'}[e.target.id];d[field]=e.target.value;if(e.target.id==='answer')$('#char-count').textContent=`${analyzeAnswer(d.text,question()).wordCount} 字元`;save();}});
document.addEventListener('keydown',e=>{if(e.target.id==='code-editor'&&e.key==='Tab'){e.preventDefault();const t=e.target,a=t.selectionStart,b=t.selectionEnd;t.value=t.value.slice(0,a)+'  '+t.value.slice(b);t.selectionStart=t.selectionEnd=a+2;t.dispatchEvent(new Event('input',{bubbles:true}));}});

document.addEventListener('click',async e=>{if(e.target.closest('.skip')){e.preventDefault();$('#main').focus();return;}const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,id=b.dataset.id;
 if(action==='close-dialog'){closeDialog();return;}
 if(action==='tour'){modal('一場練習，三個步驟',`<div class="dialog-body"><div class="step-row"><span class="step-number">01</span><div><h3>設定背景</h3><p>選擇題數與難度，填入履歷和職缺重點。</p></div></div><div class="step-row"><span class="step-number">02</span><div><h3>進入面試室</h3><p>閱讀程式、輸入回答，或錄下口頭說明供自己回聽。</p></div></div><div class="step-row"><span class="step-number">03</span><div><h3>回顧與重答</h3><p>保留第一次的回答，再嘗試補充理由與驗證方式。</p></div></div><div class="note">設定頁可選示範或 GPT 面試。GPT 模式需管理者設定金鑰，語音需麥克風權限。</div></div>`,`<div class="dialog-actions"><button class="btn primary" data-action="tour-start">開始設定 ${icon('arrow')}</button></div>`);return;}
 if(action==='tour-start'){closeDialog();go('setup');return;}
 if(action==='resume'){go('room');return;}
 if(action==='sample-resume'){$('#resume').value='資訊相關科系學生，熟悉 C 與 C++。\n曾以 C++ 製作課程專案，負責資料結構、檔案讀寫與測試。\n希望練習：說明自己的設計選擇、分析邊界情況，並具體描述驗證方法。';toast('已帶入虛構範例，可自行修改');return;}
 if(action==='hint'){hintOpen=!hintOpen;render();return;}
 if(action==='pause'){if(!current())return;current().paused=!current().paused;await stopMic();save();render();return;}
 if(action==='mic'){await toggleMic();return;}
 if(action==='reset-code'){draft().code=question().code;save();render();toast('已還原本題原始程式');return;}
 if(action==='followup'){if(current().paused)return;const d=draft();if(!d.text.trim()){toast('先輸入回答重點，再查看示範追問。');$('#answer').focus();return;}d.followupShown=true;d.followupPrompt=analyzeAnswer(d.text,question()).followup;save();render();$('#followup-answer').focus();return;}
 if(action==='next'){if(!current()||current().paused)return;const d=draft(),q=question();if(!d.text.trim()&&d.code.trim()===(q.code||'').trim()){toast('先輸入回答，或修改程式後再繼續。');$('#answer').focus();return;}await stopMic();recordAnswer();if(current().index>=current().questions.length-1){await finishSession();return;}current().index++;hintOpen=false;save();render();window.scrollTo(0,0);return;}
 if(action==='finish-early'){confirmAction('結束這場練習？','已作答的內容會保存至回顧，其他題目會標示為未作答。','confirm-finish');return;}
 if(action==='confirm-finish'){await finishSession();return;}
 if(action==='report'){reportId=id;go('report');return;}
 if(action==='export-report'){exportReport();return;}
 if(action==='retake'){editRetake(id);return;}
 if(action==='new-question'||action==='edit-question'){editQuestion(id);return;}
 if(action==='delete-question'){if(state.questions.length<=1){toast('至少保留一題才能開始練習。');return;}modal('刪除這道題目？',`<div class="dialog-body"><p>已完成的練習仍會保留原題目。新的練習將不再使用這題。</p></div>`,`<div class="dialog-actions"><button class="btn" data-action="close-dialog">取消</button><button class="btn danger" data-action="confirm-delete-question" data-id="${esc(id)}">刪除題目</button></div>`);return;}
 if(action==='confirm-delete-question'){state.questions=state.questions.filter(q=>q.id!==id);save();closeDialog();render();toast('已刪除題目');return;}
 if(action==='restore-questions'){confirmAction('恢復範例題目？','這會取代目前的題庫。建議先匯出你修改過的題目，練習紀錄不受影響。','confirm-restore');return;}
 if(action==='confirm-restore'){state.questions=structuredClone(DEFAULT_QUESTIONS);save();closeDialog();render();toast('已恢復範例題庫');return;}
 if(action==='export-questions'){download(JSON.stringify(state.questions,null,2),'preplab-questions.json','application/json');return;}
 if(action==='import-questions'){$('#question-file').click();return;}
 if(action==='delete-session'){modal('刪除此場練習？',`<div class="dialog-body"><p>這會刪除本機的回答與重答紀錄，無法復原。</p></div>`,`<div class="dialog-actions"><button class="btn" data-action="close-dialog">取消</button><button class="btn danger" data-action="confirm-delete-session" data-id="${esc(id)}">刪除紀錄</button></div>`);return;}
 if(action==='confirm-delete-session'){await features.deleteSessionRecordings(id);state.history=state.history.filter(s=>s.id!==id);save();closeDialog();render();toast('已刪除練習紀錄');return;}
 if(action==='settings'){modal('你的資料與連線狀態',`<div class="dialog-body"><h3>目前為示範模式</h3><p class="feedback-note">未連接任何 AI API，也不會將履歷、回答或錄音送往模型服務。文字與程式保存在此瀏覽器，錄音僅在本次頁面暫存。</p><div class="divider"></div><h3>本機資料</h3><p class="feedback-note">共 ${state.history.length} 場練習、${state.questions.length} 道題目。建議透過題目匯出及回顧匯出保留副本。</p><button class="btn danger" data-action="clear-data">${icon('trash')} 清除本機資料</button></div>`,`<div class="dialog-actions"><button class="btn primary" data-action="close-dialog">完成</button></div>`);return;}
 if(action==='clear-data'){closeDialog();confirmAction('清除所有本機資料？','將移除履歷、作答、練習紀錄與自訂題目，並恢復範例題庫。此操作無法復原。','confirm-clear');return;}
 if(action==='confirm-clear'){await features.disconnect();await stopMic();await features.clearRecordings();for(const u of audioURLs.values())URL.revokeObjectURL(u);audioURLs.clear();state={profile:{...DEFAULT_PROFILE},questions:structuredClone(DEFAULT_QUESTIONS),history:[],active:null};save();closeDialog();go('dashboard');toast('已清除本機資料');return;}
});

document.addEventListener('submit',async e=>{if(e.target.id==='setup-form'){e.preventDefault();const form=new FormData(e.target);const p={mode:String(form.get('mode')||'demo'),name:String(form.get('name')).trim(),role:String(form.get('role')).trim(),difficulty:String(form.get('difficulty')),count:Number(form.get('count')),resume:String(form.get('resume')),jd:String(form.get('jd'))};if(!p.role){toast('請填寫目標職務');return;}const sessionId=uid();const start=()=>features.task(async()=>{const ordered=[...state.questions.filter(q=>q.level===p.difficulty),...state.questions.filter(q=>q.level!==p.difficulty)];const generated=await features.start(p,structuredClone(buildQueue(ordered,p.count)),sessionId);await features.disconnect();await stopMic();if(state.active)await features.deleteSessionRecordings(state.active.id);state.profile=p;state.active={id:sessionId,mode:p.mode,planMeta:generated.meta||null,profile:{...p},startedAt:new Date().toISOString(),questions:generated.questions,index:0,elapsed:0,paused:false,answers:[],drafts:{}};save();go('room');});if(state.active){modal('開始新的練習？',`<div class="dialog-body"><p>你還有一場未完成的練習。開始新場次會取代該場進度，已完成的歷史紀錄不受影響。</p></div>`,`<div class="dialog-actions"><button class="btn" data-action="close-dialog">取消</button><button id="start-replace" class="btn primary">開始新練習</button></div>`);$('#start-replace').onclick=()=>{closeDialog();start();};}else start();}
 if(e.target.id==='question-form'){e.preventDefault();const f=new FormData(e.target);const checks=String(f.get('checks')).split('\n').filter(l=>l.trim()).map(l=>{const [label,...r]=l.split('|');return {label:label.trim(),keywords:r.join('|').split(/[,，]/).map(s=>s.trim()).filter(Boolean)};}).filter(c=>c.label&&c.keywords.length);const q={id:e.target.dataset.id||uid(),title:String(f.get('title')).trim(),category:String(f.get('category')).trim(),level:String(f.get('level')),prompt:String(f.get('prompt')).trim(),code:String(f.get('code')),followup:String(f.get('followup')).trim(),hint:String(f.get('hint')).trim(),checks};if(!q.title||!q.prompt||!q.followup||!q.hint){toast('請完整填寫題目、追問與提示');return;}try{validateQuestion(q);if(state.questions.length>=100&&!state.questions.some(x=>x.id===q.id))throw Error('題庫最多 100 題。');}catch(err){toast(err.message);return;}const i=state.questions.findIndex(x=>x.id===q.id);if(i>=0)state.questions[i]=q;else state.questions.push(q);save();closeDialog();render();toast('已保存，下次練習即會套用');}
 if(e.target.id==='retake-form'){e.preventDefault();const f=new FormData(e.target),text=String(f.get('retakeText')).trim();if(!text){toast('請輸入重答內容');return;}const a=selectedReport().answers.find(a=>a.questionId===e.target.dataset.id);delete a.aiComparison;a.retakeText=text;a.retakeCode=String(f.get('retakeCode')||'');save();closeDialog();render();toast('已保存重答，可對照兩次回答');}
});
document.addEventListener('change',async e=>{if(e.target.id==='resume-file'){const file=e.target.files[0];if(!file)return;if(file.size>200000||!(/\.(txt|md)$/i).test(file.name)){toast('請選擇 200 KB 以內的 TXT 或 Markdown 文字檔。');return;}try{$('#resume').value=(await file.text()).slice(0,20000);toast('已匯入文字，請確認內容後開始練習');}catch{toast('無法讀取檔案，請直接貼上文字。');}}
 if(e.target.id==='question-file'){const file=e.target.files[0];if(!file)return;try{if(file.size>1000000)throw Error();const data=JSON.parse(await file.text());if(!Array.isArray(data)||!data.length||data.length>100)throw Error();const ids=new Set();const clean=data.map(q=>{if(!q||typeof q!=='object'||!['title','prompt','category','followup','hint','code','level'].every(k=>typeof q[k]==='string')||!q.title.trim()||!q.prompt.trim()||!['基礎','進階'].includes(q.level))throw Error();const id=typeof q.id==='string'&&q.id?q.id:uid();if(ids.has(id))throw Error();ids.add(id);if(q.checks!==undefined&&(!Array.isArray(q.checks)||q.checks.some(c=>!c||typeof c.label!=='string'||!Array.isArray(c.keywords)||c.keywords.some(k=>typeof k!=='string'))))throw Error();return validateQuestion({...q,id,checks:q.checks||[]});});modal('匯入題庫？',`<div class="dialog-body"><p>將以檔案中的 ${clean.length} 道題目取代目前題庫。已開始或完成的練習不受影響。</p></div>`,`<div class="dialog-actions"><button class="btn" data-action="close-dialog">取消</button><button id="confirm-import" class="btn primary">確認匯入</button></div>`);$('#confirm-import').onclick=()=>{state.questions=clean;save();closeDialog();render();toast('已匯入題庫');};}catch{toast('題庫格式不符。請使用從本網站匯出的 JSON 格式（1–100 題）。');}}});
setInterval(()=>{if(recorder?.state==='recording'&&Date.now()-recordStarted>300000){stopMic();toast('已達單次五分鐘錄音上限，錄音已停止。');}if(current()&&!current().paused&&location.hash==='#room'){current().elapsed=(current().elapsed||0)+1;const t=$('#timer');if(t)t.textContent=duration(current().elapsed);if(current().elapsed%5===0)save();}if(recorder?.state==='recording'){const label=$('#mic-label');if(label)label.textContent=`停止錄音 · ${duration(Math.floor((Date.now()-recordStarted)/1000))}`;}},1000);
window.addEventListener('beforeunload',()=>{save();stopMic();});
render();

features.ready();
